"""Stimulus injector for a FISH Autoware run: once localization is initialized, give the logging_simulator a route through
the AD API (goal from sim_route_tool.py's route.json), so that planning and control compute for real during the replay.
Runs INSIDE the container (plain ros2 binary, no FISH wrapper), started by the FISH ros2 wrapper FISH_INJECT_AT seconds after
the replay starts (FISH_INJECT_CMD). Logs to stdout (the wrapper redirects to fishlog/inject.log).
  usage: inject_route.py <route.json> [--wait-init 90] [--autonomous]"""
import argparse, json, os, subprocess, sys, time

R2 = '/opt/ros/humble/bin/ros2'
ap = argparse.ArgumentParser(); ap.add_argument('route'); ap.add_argument('--wait-init', type=float, default=90); ap.add_argument('--autonomous', action='store_true')
ap.add_argument('--wait-move', type=float, default=60, help='then wait until the ego moves faster than --min-speed (it leaves the parking spot onto a forward lane)')
ap.add_argument('--min-speed', type=float, default=1.0); ap.add_argument('--after-move', type=float, default=2.0, help='seconds after the first motion before the route is set')
a = ap.parse_args()
env = dict(os.environ); env.pop('LD_PRELOAD', None); env['FISH_ENABLED'] = '0'     # the injector itself is not traced
route = json.load(open(a.route)); cmds = route['adapi']
log = lambda m: print(f"[inject {time.strftime('%H:%M:%S')}] {m}", flush=True)
def sh(c, t=40):
    try: return subprocess.run(c, shell=True, env=env, capture_output=True, text=True, timeout=t).stdout.strip()
    except subprocess.TimeoutExpired: return 'TIMEOUT'
t0 = time.time(); state = ''
while time.time() - t0 < a.wait_init:
    out = sh(f"{R2} topic echo --once /api/localization/initialization_state 2>/dev/null | grep '^state'", 10)
    if 'state: 3' in out: state = out; break
    time.sleep(2)
log(f"localization initialization_state: {state or 'not initialized after %.0f s' % a.wait_init}")
t1 = time.time(); v = 0.0
while time.time() - t1 < a.wait_move:
    out = sh(f"{R2} topic echo --once /localization/kinematic_state --no-arr 2>/dev/null | grep -A1 'linear:' | grep 'x:'", 10)
    try: v = float(out.split('x:')[1].strip())
    except Exception: v = 0.0
    if abs(v) >= a.min_speed: break
    time.sleep(1)
log(f"ego speed {v:.2f} m/s after {time.time() - t1:.0f} s of waiting for motion; setting the route in {a.after_move:g} s")
time.sleep(a.after_move)
pose = sh(f"{R2} topic echo --once /localization/kinematic_state --no-arr 2>/dev/null | grep -A2 'position:' | tr -s ' ' | tr '\\n' ' '", 10)
log(f"ego pose: {pose}")
out = sh(cmds['set_route_points'], 60); log(f"set_route_points -> {out[-200:]}")
ok = 'success=True' in out
for k in range(3):
    if ok: break
    time.sleep(4); out = sh(cmds['set_route_points'], 60); log(f"set_route_points retry {k + 1} -> {out[-200:]}"); ok = 'success=True' in out
time.sleep(2)
log(f"routing state: {sh(f'{R2} topic echo --once /api/routing/state 2>/dev/null | grep ^state', 10)}")
if a.autonomous and ok:
    log(f"change_to_autonomous -> {sh(cmds['autonomous'], 40)[-160:]}")
for k in range(2):
    time.sleep(6)
    log(f"trajectory: {sh(f'{R2} topic hz /planning/scenario_planning/trajectory 2>&1 | grep -m1 average', 10)}; control_cmd: {sh(f'{R2} topic hz /control/command/control_cmd 2>&1 | grep -m1 average', 10)}")
log(f"done (route ok={ok})"); sys.exit(0 if ok else 1)
